begin;
create table public.invoice_claims(organization_id uuid not null,contractor_id uuid not null,invoice_id text not null,run_id uuid not null,primary key(organization_id,contractor_id,invoice_id),foreign key(organization_id,contractor_id) references public.contractors(organization_id,id),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
alter table public.invoice_claims enable row level security;
create policy member_read on public.invoice_claims for select to authenticated using(public.member_of(organization_id));
revoke all on public.invoice_claims from anon,authenticated;grant select on public.invoice_claims to authenticated;grant all on public.invoice_claims to service_role;
create function public.approve_payroll(p_org uuid,p_run uuid,p_user uuid,p_hash text,p_wallet text,p_bytes text,p_digest text,p_expires timestamptz) returns void language plpgsql security definer set search_path='' as $$ declare r public.payroll_runs; p jsonb; i text;begin select * into r from public.payroll_runs where id=p_run and organization_id=p_org for update;if r.status not in ('PREPARED','READY','APPROVED') or r.plan->>'hash'<>p_hash then raise exception 'Payment plan changed';end if;if not exists(select 1 from public.memberships where organization_id=p_org and user_id=p_user and role in ('owner','admin','approver')) then raise exception 'Not authorized';end if;for p in select * from jsonb_array_elements(r.plan->'payments') loop for i in select jsonb_array_elements_text(p->'invoiceIds') loop if exists(select 1 from public.paid_invoices where organization_id=p_org and contractor_id=(p->>'contractorId')::uuid and invoice_id=lower(trim(i))) then raise exception 'Invoice already paid';end if;insert into public.invoice_claims values(p_org,(p->>'contractorId')::uuid,lower(trim(i)),p_run) on conflict do nothing;if not exists(select 1 from public.invoice_claims where organization_id=p_org and contractor_id=(p->>'contractorId')::uuid and invoice_id=lower(trim(i)) and run_id=p_run) then raise exception 'Invoice reserved by another payroll';end if;end loop;end loop;insert into public.approvals(organization_id,run_id,plan_hash,user_id,wallet,transaction_bytes,transaction_digest,expires_at) values(p_org,p_run,p_hash,p_user,p_wallet,p_bytes,p_digest,p_expires) on conflict(run_id,plan_hash) do update set user_id=excluded.user_id,wallet=excluded.wallet,transaction_bytes=excluded.transaction_bytes,transaction_digest=excluded.transaction_digest,expires_at=excluded.expires_at;update public.payroll_runs set status='APPROVED' where id=p_run;insert into public.audit_logs(organization_id,user_id,run_id,action,metadata) values(p_org,p_user,p_run,'Payment approved',jsonb_build_object('planHash',p_hash));end $$;
revoke all on function public.approve_payroll(uuid,uuid,uuid,text,text,text,text,timestamptz) from public,anon,authenticated;grant execute on function public.approve_payroll(uuid,uuid,uuid,text,text,text,text,timestamptz) to service_role;
commit;
